mapper.select:
/* SelectMngMapper.selectSelectionList : 목록선별 리스트 조회 */
SELECT od.HBL_NO ,od.PIECES ,od.GWT ,od.AMOUNT_LOC ,od.AMOUNT_CUR ,od.COMMODITY_ITEM ,od.ALLOWED_ITEM_CODE ,od.URL ,od.CONSIGNEE_NAME ,od.CONSIGNEE_ADDRESS ,od.CONSIGNEE_COUNTRY_CODE ,od.SHIPPER_NAME ,od.SHIPPER_ADDRESS ,od.SHIPPER_TEL ,od.SHIPPER_COUNTRY_CODE ,od.DEST_CODE ,od.DEST_COUNTRY ,dbo.Cryptography(od.OD_JOB_NO, od.SHIPPER_BUSINESS_ID, 1) AS SHIPPER_BUSINESS_ID ,od.OD_JOB_NO ,od.MASTER_OD_JOB_NO ,od.BOUND ,od.BOUND_TYPE ,ISNULL(od.AMOUNT_USD, 0) AS AMOUNT_USD ,ISNULL(od.ORIG_COUNTRY, '') AS ORIG_COUNTRY_CODE ,ad.CRIME_AREA_YN ,ad.ACTUAL_CST_NAME ,od.CD_TYPE ,od.INSPECTION_YN ,od.CD_USE_TYPE ,od.ECM_TYPE ,od.DOCUMENT_YN ,CASE WHEN ad.SELECTION_YN = 'Y' THEN '' ELSE sel.CHECK_INFO END AS CHECK_INFO ,CASE WHEN ad.SELECTION_YN = 'Y' THEN '' ELSE sel.SELECTION_TYPE END AS SELECTION_TYPE ,CASE WHEN ad.SELECTION_YN = 'Y' OR sel.OD_JOB_NO IS NULL THEN 'N' ELSE sel.DATA_CHANGE_YN END AS DATA_CHANGE_YN
,dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_TEL_ENC, 1) AS CONSIGNEE_TEL ,dbo.Cryptography(od.OD_JOB_NO, od.CUSTOMS_ID_ENC, 1) AS CUSTOMS_ID
,od.CONSIGNEE_TEL ,od.CUSTOMS_ID
,ad.SIMPLE_DOC_NO ,od.CUST_CODE_LV1 ,od.CUST_CODE_LV2 ,od.PIECES_REAL FROM TB_ECM_OD od LEFT JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO LEFT JOIN TB_ECM_OD_SELECTION sel ON sel.HOUSE_OD_JOB_NO = od.OD_JOB_NO
AND sel.AUTO_SELECTION_YN = 'N'
AND sel.AUTO_SELECTION_YN = 'Y'
WHERE od.OD_JOB_NO = #{srchOdJobNo}
WHERE od.OD_JOB_NO IN(#{item})
WHERE od.MASTER_OD_JOB_NO = #{srchMasterOdJobNo}
AND od.BOUND_TYPE = 'IMP' AND od.BL_TYPE_MH = 'H'
AND od.CD_TYPE = #{srchCdType}
AND od.CD_USE_TYPE = #{srchCdUseType}
AND od.ECM_TYPE = #{srchEcmType}
AND od.INSPECTION_YN = #{srchInspectionYn}
AND ad.CRIME_AREA_YN = #{srchCrimeAreaYn}

/* SelectMngMapper.selectTempSelectionList : 목록선별 임시저장 리스트 조회 */
SELECT A.HBL_NO ,A.PIECES ,A.GWT ,A.AMOUNT_LOC ,A.AMOUNT_CUR ,A.COMMODITY_ITEM ,A.ALLOWED_ITEM_CODE ,A.URL ,A.CONSIGNEE_NAME ,A.CONSIGNEE_ADDRESS ,A.CUSTOMS_ID ,A.CONSIGNEE_TEL ,A.CONSIGNEE_COUNTRY_CODE ,A.SHIPPER_NAME ,A.SHIPPER_ADDRESS ,A.SHIPPER_TEL ,A.SHIPPER_COUNTRY_CODE ,A.DEST_CODE ,A.OD_JOB_NO ,A.MASTER_OD_JOB_NO ,A.BOUND ,A.BOUND_TYPE ,A.AMOUNT_USD ,A.ORIG_COUNTRY_CODE ,A.CRIME_AREA_YN ,A.INSPECTION_YN ,A.CHECK_INFO ,A.SELECTION_TYPE ,A.DATA_CHANGE_YN ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE GROUP_CODE = 'CD_TYPE' AND CODE = A.CD_TYPE) AS CD_TYPE ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE GROUP_CODE = 'USE_GUBN' AND CODE = A.CD_USE_TYPE) AS CD_USE_TYPE ,(SELECT NAME_${userLanguage} FROM TB_SMS_CODE_DETAIL WHERE GROUP_CODE = 'CCL_ECOMMERCE_TYPE' AND CODE = A.ECM_TYPE) AS ECM_TYPE FROM(
SELECT A.* FROM(
SELECT od.HBL_NO ,od.PIECES ,od.GWT ,od.AMOUNT_LOC ,od.AMOUNT_CUR ,od.COMMODITY_ITEM ,od.URL ,od.CONSIGNEE_NAME ,od.CONSIGNEE_ADDRESS ,od.CONSIGNEE_COUNTRY_CODE ,od.SHIPPER_NAME ,od.SHIPPER_ADDRESS ,od.SHIPPER_TEL ,od.SHIPPER_COUNTRY_CODE ,od.DEST_CODE ,od.OD_JOB_NO ,od.MASTER_OD_JOB_NO ,od.BOUND ,od.BOUND_TYPE ,ISNULL(od.AMOUNT_USD, 0) AS AMOUNT_USD ,ISNULL(od.ORIG_COUNTRY, '') AS ORIG_COUNTRY_CODE ,ad.CRIME_AREA_YN ,CASE WHEN ad.SELECTION_YN = 'Y' THEN od.INSPECTION_YN ELSE ISNULL(sel.INSPECTION_YN, od.INSPECTION_YN) END AS INSPECTION_YN ,CASE WHEN ad.SELECTION_YN = 'Y' THEN '' ELSE sel.CHECK_INFO END AS CHECK_INFO ,CASE WHEN ad.SELECTION_YN = 'Y' THEN '' ELSE sel.SELECTION_TYPE END AS SELECTION_TYPE ,CASE WHEN ad.SELECTION_YN = 'Y' OR sel.OD_JOB_NO IS NULL THEN 'N' ELSE sel.DATA_CHANGE_YN END AS DATA_CHANGE_YN ,CASE WHEN ad.SELECTION_YN = 'Y' THEN od.CD_TYPE ELSE ISNULL(sel.CD_TYPE, od.CD_TYPE) END AS CD_TYPE ,CASE WHEN ad.SELECTION_YN = 'Y' THEN od.CD_USE_TYPE ELSE ISNULL(sel.CD_USE_TYPE, od.CD_USE_TYPE) END AS CD_USE_TYPE ,CASE WHEN ad.SELECTION_YN = 'Y' THEN od.ECM_TYPE ELSE ISNULL(sel.ECM_TYPE, od.ECM_TYPE) END AS ECM_TYPE ,CASE WHEN ad.SELECTION_YN = 'Y' THEN od.ALLOWED_ITEM_CODE ELSE ISNULL(sel.ALLOWED_ITEM_CODE, od.ALLOWED_ITEM_CODE) END AS ALLOWED_ITEM_CODE
,dbo.Cryptography(od.OD_JOB_NO, od.CONSIGNEE_TEL_ENC, 1) AS CONSIGNEE_TEL ,dbo.Cryptography(od.OD_JOB_NO, od.CUSTOMS_ID_ENC, 1) AS CUSTOMS_ID
,od.CONSIGNEE_TEL ,od.CUSTOMS_ID
FROM TB_ECM_OD od LEFT JOIN TB_ECM_OD_ADDITIONAL ad ON ad.OD_JOB_NO = od.OD_JOB_NO LEFT JOIN TB_ECM_OD_SELECTION sel ON sel.HOUSE_OD_JOB_NO = od.OD_JOB_NO
AND sel.AUTO_SELECTION_YN = 'N'
AND sel.AUTO_SELECTION_YN = 'Y'
WHERE od.OD_JOB_NO IN(#{item})
WHERE od.MASTER_OD_JOB_NO = #{srchMasterOdJobNo}
AND od.BOUND_TYPE = 'IMP' AND od.BL_TYPE_MH = 'H'
AND ad.CRIME_AREA_YN = #{srchCrimeAreaYn}
) A WHERE 1 = 1
AND A.CD_TYPE = #{srchCdType}
AND A.CD_USE_TYPE = #{srchCdUseType}
AND A.ECM_TYPE = #{srchEcmType}
AND A.INSPECTION_YN = #{srchInspectionYn}

/* SelectMngMapper.selectItenName : 세부품목 조회 */
WITH TMP AS ( SELECT item.DETAIL_ITEM_NAME AS OD_ITEM_NAME ,dbo.GetRegExReplace(item.DETAIL_ITEM_NAME, '[^a-z0-9]', '') AS OD_ITEM_NAME_REPLACE ,item.HS_CODE AS OD_HS_CODE ,item.SEQ_NO_ID ,od.INSPECTION_YN ,od.OD_JOB_NO ,od.CD_USE_TYPE ,od.ECM_TYPE ,ISNULL(od.AMOUNT_USD, 0) AS AMOUNT_USD FROM TB_ECM_OD od LEFT JOIN TB_ECM_OD_ITEM item ON item.OD_JOB_NO = od.OD_JOB_NO WHERE od.OD_JOB_NO = #{odJobNo} ) SELECT A.* FROM( SELECT od.* ,goods.ITEM_NAME ,goods.CD_YTYPE_YN ,goods.CD_BTYPE_YN ,goods.HS_CODE ,ROW_NUMBER() OVER(PARTITION BY od.OD_JOB_NO,od.SEQ_NO_ID ORDER BY od.OD_JOB_NO) AS ROW_NUM FROM TMP od LEFT JOIN TB_ECM_GOODS_SELECTION_INFO goods
ON goods.ITEM_NAME = od.OD_ITEM_NAME_REPLACE
ON goods.ITEM_NAME LIKE CONCAT(SUBSTRING(od.OD_ITEM_NAME_REPLACE, 1, LEN(od.OD_ITEM_NAME_REPLACE) * ${srchRatio} / 10), '%')
) A WHERE A.ROW_NUM = 1 ORDER BY A.SEQ_NO_ID
SELECT item.DETAIL_ITEM_NAME AS OD_ITEM_NAME ,item.HS_CODE AS OD_HS_CODE ,item.SEQ_NO_ID ,od.INSPECTION_YN ,od.OD_JOB_NO ,od.CD_USE_TYPE ,od.ECM_TYPE ,ISNULL(od.AMOUNT_USD, 0) AS AMOUNT_USD FROM TB_ECM_OD od LEFT JOIN TB_ECM_OD_ITEM item ON item.OD_JOB_NO = od.OD_JOB_NO WHERE od.OD_JOB_NO = #{odJobNo} ORDER BY item.SEQ_NO_ID

/* SelectMngMapper.selectChkItemNameList : 선별 리스트 조회(세부품목과 비교할 내용) */ SELECT ETC1 AS SEARCH_TYPE ,ETC2 AS KEYWORD ,ETC3 AS OPERATOR ,ETC4 AS CHECK_FIELD ,ETC5 AS DESCRIPTION ,ETC7 AS DOCUMENT_YN FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE = 'GOODS_SELECTION' AND ETC1 IN(#{item}) AND ETC4 IN('DetailItemName', 'HsCode')
AND (ETC1 != '3Y' OR ETC4 IN(#{item}))
ORDER BY ETC1 DESC

/* SelectMngMapper.selectChkOtherList : 선별 리스트 조회(오더항목과 비교할 내용) */ SELECT ETC1 AS SEARCH_TYPE ,ETC2 AS KEYWORD ,ETC3 AS OPERATOR ,CASE ETC4 WHEN 'DetailItemName' THEN 'CommodityItem' WHEN 'HsCode' THEN 'AllowedItemCode' ELSE ETC4 END AS CHECK_FIELD ,ETC5 AS DESCRIPTION ,ETC7 AS DOCUMENT_YN FROM TB_SMS_CODE_DETAIL WHERE ENT_CODE = #{srchEntCode} AND GROUP_CODE = 'GOODS_SELECTION' AND ETC1 IN(#{item})
AND (ETC1 != '3Y' OR ETC4 IN(#{item}))
ORDER BY ETC1 DESC

/* SelectMngMapper.selectGoodsSelectionDupChk : GOODS_SELECTION_INFO 중복체크 */
	WITH TMP AS (
		SELECT ITEM_NAME
		FROM TB_ECM_GOODS_SELECTION_INFO
		WHERE ITEM_NAME IN(


		dbo.GetRegExReplace(#{item.itemName}, '[^a-z0-9]', '')


		dbo.GetRegExReplace(#{item}, '[^a-z0-9]', '')


		)
	)
	SELECT STUFF((SELECT ',' + ITEM_NAME FROM TMP FOR XML PATH('')), 1, 1, '') AS ITEM_NAME

mapper.delete:
/* SelectMngMapper.deleteTempSelection : 선별오더임시데이터 삭제 */
	DELETE FROM TB_ECM_OD_SELECTION
	WHERE OD_JOB_NO = #{masterOdJobNo}

	AND HOUSE_OD_JOB_NO IN(#{item})

/* SelectMngMapper.deleteOtherTempSelection : 다른메뉴선별오더임시데이터 삭제 */
	DELETE FROM TB_ECM_OD_SELECTION
	WHERE OD_JOB_NO = #{masterOdJobNo}


	AND AUTO_SELECTION_YN = 'N';


	AND AUTO_SELECTION_YN = 'Y';
	DELETE FROM TB_ECM_OD_SELECTION_ITEM
	WHERE OD_JOB_NO = #{masterOdJobNo};
	DELETE FROM TB_ECM_OD_SELECTION_ITEM_HBL
	WHERE OD_JOB_NO = #{masterOdJobNo};

/* SelectMngMapper.deleteTempSelectionItem : 선별품명임시데이터 삭제 */
	DELETE FROM TB_ECM_OD_SELECTION_ITEM
	WHERE OD_JOB_NO = #{masterOdJobNo};
	DELETE FROM TB_ECM_OD_SELECTION_ITEM_HBL
	WHERE OD_JOB_NO = #{masterOdJobNo};

mapper.insert:
/* SelectMngMapper.insertTempSelection : 선별오더임시저장 */
	INSERT INTO TB_ECM_OD_SELECTION(
		   OD_JOB_NO
		  ,HOUSE_OD_JOB_NO
		  ,CD_TYPE
		  ,INSPECTION_YN
		  ,CD_USE_TYPE
		  ,ECM_TYPE
		  ,CHECK_INFO
		  ,SELECTION_TYPE
		  ,AUTO_SELECTION_YN
		  ,CRIME_AREA_YN
		  ,ALLOWED_ITEM_CODE
		  ,ITEM_NAME
		  ,DATA_CHANGE_YN
		  ,REGISTER_USER_ID
		  ,REGISTER_DATE_TIME
		  ,UPDATE_USER_ID
		  ,UPDATE_DATE_TIME
	)VALUES(
		   #{masterOdJobNo}
		  ,#{odJobNo}
		  ,#{cdType}
		  ,#{inspectionYn}
		  ,#{cdUseType}
		  ,#{ecmType}
		  ,#{checkInfo}
		  ,#{selectionType}
		  ,#{autoSelectionYn}
		  ,#{crimeAreaYn}
		  ,#{allowedItemCode}
		  ,#{selectionItemName}
		  ,#{dataChangeYn}
		  ,#{registerUserId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
		  ,#{registerUserId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
	)

/* SelectMngMapper.insertTempSelectionItem : 선별품명임시저장 */
	INSERT INTO TB_ECM_OD_SELECTION_ITEM(
		   OD_JOB_NO
		  ,SEQ_NO_ID
		  ,ITEM_NAME
		  ,ALLOWED_ITEM_CODE
		  ,CD_TYPE_YT_YN
		  ,CD_TYPE_BT_YN
		  ,INSPECTION_YN
		  ,REVIEW_YN
		  ,REGISTER_USER_ID
		  ,REGISTER_DATE_TIME
		  ,UPDATE_USER_ID
		  ,UPDATE_DATE_TIME
	)VALUES(
		   #{masterOdJobNo}
		  ,#{seqNoId}
		  ,#{itemName}
		  ,#{hsCode}
		  ,#{cdYtypeYn}
		  ,#{cdBtypeYn}
		  ,#{inspectionYn}
		  ,#{reviewYn}
		  ,#{updateUserId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
		  ,#{updateUserId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
	)

mapper.update:
/* SelectMngMapper.updateTempSelectionItem : 선별품명임시저장 */
	UPDATE TB_ECM_OD_SELECTION_ITEM SET
		   ALLOWED_ITEM_CODE = #{hsCode}
		  ,CD_TYPE_YT_YN = #{cdYtypeYn}
		  ,CD_TYPE_BT_YN = #{cdBtypeYn}
		  ,INSPECTION_YN = #{inspectionYn}
		  ,REVIEW_YN = #{reviewYn}
	WHERE OD_JOB_NO = #{masterOdJobNo}
	AND SEQ_NO_ID = #{seqNoId}

/* SelectMngMapper.updateSelectionList : 목록선별 리스트 수정 */
	UPDATE TB_ECM_OD SET
		   CD_TYPE = #{cdType}

		  ,INSPECTION_YN = #{inspectionYn}
		  ,CD_USE_TYPE = #{cdUseType}
		  ,ECM_TYPE = #{ecmType}

	WHERE OD_JOB_NO = #{odJobNo};

	UPDATE TB_ECM_OD_ADDITIONAL SET
		   CD_TYPE = #{cdType}
	WHERE OD_JOB_NO = #{odJobNo};

/* SelectMngMapper.updateSelectionHsList : 선별 HsCode 업데이트 */
	UPDATE TB_ECM_OD_ITEM SET
		   HS_CODE = #{hsCode}
	WHERE OD_JOB_NO = #{odJobNo}





	AND DETAIL_ITEM_NAME = #{itemName};


	UPDATE TB_ECM_OD SET
		   ALLOWED_ITEM_CODE = #{hsCode}
	WHERE OD_JOB_NO = #{odJobNo};

/* SelectMngMapper.updateInspectionList : 선별 검사YN 업데이트 */
	UPDATE TB_ECM_OD SET
		   INSPECTION_YN = #{inspectionYn}
	WHERE OD_JOB_NO = #{odJobNo}

/* SelectMngMapper.updateSelectionClearanceStatus : 목록선별 수정시 목록이 아닐경우 통관상태 신고전으로 수정 */
	UPDATE TB_ECM_OD_ADDITIONAL SET
		   CLEARANCE_STATUS = CASE WHEN ISNULL(CLEARANCE_STATUS, '') = '' THEN 'CLS010' ELSE CLEARANCE_STATUS END
	WHERE OD_JOB_NO = #{odJobNo}

/* SelectMngMapper.updateSelectionYn : 목록선별 선별마감/마감해제 */
	UPDATE ad SET
		   ad.SELECTION_YN = #{selectionYn}
	FROM TB_ECM_OD od
		 INNER JOIN TB_ECM_OD_ADDITIONAL ad
		 			ON ad.OD_JOB_NO = od.OD_JOB_NO
	WHERE od.MASTER_OD_JOB_NO = #{masterOdJobNo}

mapper.select:
/* SelectMngMapper.selectSelectionYn : 목록선별 선별마감시 기존상태 체크 */
	SELECT SELECTION_YN
	FROM TB_ECM_OD_ADDITIONAL
	WHERE OD_JOB_NO = #{masterOdJobNo}

/* SelectMngMapper.insertGoodsSelectionInfo : 통관목록 자동선별(기초) 저장 */
	DECLARE @ITEM_NAME NVARCHAR(200) = dbo.GetRegExReplace(#{itemName}, '[^a-z0-9]', '');
	INSERT INTO TB_ECM_GOODS_SELECTION_INFO(
		   ITEM_NAME
		  ,HS_CODE
		  ,CD_YTYPE_YN
		  ,CD_BTYPE_YN
		  ,REGISTER_USER_ID
		  ,REGISTER_DATE_TIME
		  ,UPDATE_USER_ID
		  ,UPDATE_DATE_TIME
	)VALUES(
		   @ITEM_NAME
		  ,#{hsCode}
		  ,#{cdYtypeYn}
		  ,#{cdBtypeYn}
		  ,#{updateUserId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
		  ,#{updateUserId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
	);
	SELECT @ITEM_NAME AS ITEM_NAME;

mapper.insert:
/* SelectMngMapper.insertGoodsSelectionInfoBatch : 통관목록 자동선별(기초) 저장(엑셀업로드) */
