		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
	)

/* SelectMngMapper.insertGoodsSelectionInfoBackupFile : 통관목록 자동선별(기초) 저장(backup File 업데이트) */
	INSERT INTO TB_ECM_GOODS_SELECTION_INFO(
