		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
		  ,#{updateUserId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
	)

mapper.update:
/* SelectMngMapper.updateGoodsSelectionInfo : 통관목록 자동선별(기초) 수정 */
	UPDATE TB_ECM_GOODS_SELECTION_INFO SET
		   HS_CODE = #{hsCode}
		  ,CD_YTYPE_YN = #{cdYtypeYn}
		  ,CD_BTYPE_YN = #{cdBtypeYn}
		  ,UPDATE_USER_ID = #{updateUserId}
		  ,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
	WHERE ITEM_NAME = #{itemName}

mapper.delete:
/* SelectMngMapper.deleteGoodsSelectionInfo : 통관목록 자동선별(기초) 삭제 */
	DELETE FROM TB_ECM_GOODS_SELECTION_INFO
	WHERE ITEM_NAME IN (#{item.itemName})

mapper.insert:
/* SelectMngMapper.insertSelfSelection : 통관목록 자체선별(기초) 저장 */

	SELECT CASE WHEN MAX(CODE) IS NULL THEN '000000001'
  				ELSE CONCAT(REPLICATE('0', 9 - LEN(MAX(CODE) + 1)), MAX(CODE) + 1) END
  	FROM TB_SMS_CODE_DETAIL
  	WHERE GROUP_CODE = 'GOODS_SELECTION'

	INSERT INTO TB_SMS_CODE_DETAIL(
		   ENT_CODE
		  ,CODE_DEFINE_ID
		  ,CODE
		  ,GROUP_CODE
		  ,ETC1
		  ,ETC2
		  ,ETC3
		  ,ETC4
		  ,ETC5
		  ,ETC6
		  ,ETC7
		  ,REGISTER_USER_ID
		  ,REGISTER_DATE_TIME
		  ,UPDATE_USER_ID
		  ,UPDATE_DATE_TIME
	)VALUES(
		   #{entCode}
		  ,'ECM-014'
		  ,#{jobNo}
		  ,'GOODS_SELECTION'
		  ,#{selectionTarget}
		  ,#{keyword}
		  ,#{operator}
		  ,#{dataField}
		  ,#{remarks}
		  ,#{updateHsCode}
		  ,#{documentYn}
		  ,#{updateUserId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
		  ,#{updateUserId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
	)

/* SelectMngMapper.insertSelfSelectionExcelUpload : 통관목록 자체선별(기초) 저장 엑셀업로드 */
	INSERT INTO TB_SMS_CODE_DETAIL(
		   ENT_CODE
		  ,CODE_DEFINE_ID
		  ,CODE
		  ,GROUP_CODE
		  ,ETC1
		  ,ETC2
		  ,ETC3
		  ,ETC4
		  ,ETC5
		  ,ETC6
		  ,ETC7
		  ,REGISTER_USER_ID
		  ,REGISTER_DATE_TIME
		  ,UPDATE_USER_ID
		  ,UPDATE_DATE_TIME
	)VALUES(
		   #{entCode}
		  ,'ECM-014'
		  ,(
		  	SELECT CASE WHEN MAX(CODE) IS NULL THEN '000000001'
		  				ELSE CONCAT(REPLICATE('0', 9 - LEN(MAX(CODE) + 1)), MAX(CODE) + 1) END
		  	FROM TB_SMS_CODE_DETAIL
		  	WHERE GROUP_CODE = 'GOODS_SELECTION'
		   )
		  ,'GOODS_SELECTION'
		  ,#{selectionTarget}
		  ,#{keyword}
		  ,#{operator}
		  ,#{dataField}
		  ,#{remarks}
		  ,#{updateHsCode}
		  ,#{documentYn}
		  ,#{updateUserId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
		  ,#{updateUserId}
		  ,DATEADD(HOUR, ${gmtTime}, GETDATE())
	)

mapper.update:
/* SelectMngMapper.updateSelfSelection : 통관목록 자체선별(기초) 수정 */
	UPDATE TB_SMS_CODE_DETAIL SET
		   ETC1 = #{selectionTarget}
		  ,ETC2 = #{keyword}
		  ,ETC3 = #{operator}
		  ,ETC4 = #{dataField}
		  ,ETC5 = #{remarks}
		  ,ETC6 = #{updateHsCode}
		  ,ETC7 = #{documentYn}
		  ,UPDATE_USER_ID = #{updateUserId}
		  ,UPDATE_DATE_TIME = DATEADD(HOUR, ${gmtTime}, GETDATE())
	WHERE ENT_CODE = #{entCode} 
	AND GROUP_CODE = 'GOODS_SELECTION'
	AND CODE = #{jobNo}

mapper.delete:
/* SelectMngMapper.deleteGoodsSelectionInfo : 통관목록 자체선별(기초) 삭제 */
	DELETE FROM TB_SMS_CODE_DETAIL
	WHERE ENT_CODE = #{entCode} 
	AND GROUP_CODE = 'GOODS_SELECTION'
	AND CODE IN (#{item})

mapper.select:
/* SelectMngMapper.selectSelfSelectionList : 통관목록 자체선별(기초)리스트 조회 */

	SELECT
		 selection.CODE AS JOB_NO
		,CASE selection.ETC1 WHEN 'OB' THEN '배제' WHEN 'ON' THEN '일반' WHEN '3Y' THEN '검사요청' WHEN 'ZX' THEN '우범대상' WHEN 'HS' THEN '품목코드' WHEN 'JK' THEN 'HSCODE 오류' END AS SELECTION_TARGET
		,selection.ETC2 AS KEYWORD
		,CASE selection.ETC3 WHEN '0' THEN '키워드동일' WHEN '1' THEN '키워드포함' WHEN '2' THEN '이상' WHEN '3' THEN '이하' END AS OPERATOR
		,selection.ETC4 AS DATA_FIELD
		,selection.ETC5 AS REMARKS
		,selection.ETC7 AS DOCUMENT_YN
		,selection.USE_YN 
		,selection.REGISTER_DATE_TIME
		,selection.UPDATE_DATE_TIME
		,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = selection.ENT_CODE AND USER_ID = selection.REGISTER_USER_ID) AS REGISTER_USER_NAME
		,(SELECT USER_NAME FROM TB_SMS_USER WHERE ENT_CODE = selection.ENT_CODE AND USER_ID = selection.UPDATE_USER_ID) AS UPDATE_USER_NAME
	FROM TB_SMS_CODE_DETAIL selection
	WHERE selection.ENT_CODE = #{srchEntCode} 
	AND selection.GROUP_CODE = 'GOODS_SELECTION'

	AND selection.USE_YN = #{srchUseYn}


	AND selection.ETC1 = #{srchSelectionTarget}


	AND selection.ETC2 = #{srchKeyword}


	AND selection.ETC4 = #{srchDataField}


	AND selection.ETC3 = #{srchOperator}


	AND selection.ETC7 = #{srchDocumentYn}


	AND selection.${srchDateGbn} >= CONVERT(DATE, #{srchStartDate}, ${srchDateFormat}) 


	AND selection.${srchDateGbn} <= DATEADD(DAY, 1, CONVERT(DATE, #{srchEndDate}, ${srchDateFormat}))

mapper.update:
/* SelectMngMapper.updateSelectionSimpleDocNo : 목록선별 리스트 제출번호 수정 */
	UPDATE TB_ECM_OD_ADDITIONAL SET
		   SIMPLE_DOC_NO = #{simpleDocNo}
	WHERE OD_JOB_NO = #{odJobNo}
